"use strict";(self.webpackChunkwebsite=self.webpackChunkwebsite||[]).push([["9334"],{7925(e,t,o){o.r(t),o.d(t,{metadata:()=>n,default:()=>p,frontMatter:()=>i,contentTitle:()=>r,toc:()=>c,assets:()=>l});var n=JSON.parse('{"id":"reference/monitor/howtos/applyWorkflows","title":"How to configure systems using Apply Workflow(s)?","description":"alms \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. Original page.","source":"@site/docs/reference/monitor/howtos/applyWorkflows.md","sourceDirName":"reference/monitor/howtos","slug":"/reference/monitor/howtos/applyWorkflows","permalink":"/personal-av-docs/docs/reference/monitor/howtos/applyWorkflows","draft":false,"unlisted":false,"editUrl":"https://github.com/andreyjv/personal-av/tree/docs/documentation-revamp/PRD_documentation-revamp/website/docs/reference/monitor/howtos/applyWorkflows.md","tags":[],"version":"current","sidebarPosition":99,"frontMatter":{"title":"How to configure systems using Apply Workflow(s)?","sidebar_label":"How to configure systems using Apply Wor","sidebar_position":99,"edition":"alms","source":"https://doc.airvantage.net/alms/reference/monitor/howtos/applyWorkflows","format":"md"}}'),a=o(4848),s=o(8453);let i={title:"How to configure systems using Apply Workflow(s)?",sidebar_label:"How to configure systems using Apply Wor",sidebar_position:99,edition:"alms",source:"https://doc.airvantage.net/alms/reference/monitor/howtos/applyWorkflows",format:"md"},r,l={},c=[];function d(e){let t={a:"a",li:"li",p:"p",strong:"strong",ul:"ul",...(0,s.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsxs)(t.p,{children:[":::note Edition\n",(0,a.jsx)(t.strong,{children:"alms"})," \xb7 imported from live Hugo on 2026-10-07. Guides stay latest. ",(0,a.jsx)(t.a,{href:"https://doc.airvantage.net/alms/reference/monitor/howtos/applyWorkflows",children:"Original page"}),".\n:::"]}),"\n",(0,a.jsx)(t.p,{children:"How to configure systems using Apply Workflow(s)?\nUsing Workflows\nThe Apply Workflow(s) operation simplifies system configuration. Instead of applying actions to your system(s) separately, you can arrange separate actions into a workflow, and let AirVantage execute those actions in the order you want.\nThe Apply Workflow(s) window offers several pre-defined workflows in the left-hand column. In the main column, by default, it shows you the Basic Workflow, which includes:\nConfigure Communication\n: Communication intervals with AirVantage and scheduled reports\nInstall Firmware\nThe default Apply Workflow(s) window also includes an\nApply Template\noperation.\nThe other pre-defined workflows are\nInstall AAF Application\nand\nConfigure ALMS ARA\n(available only in the ALMS ARA offer class on an MP70 device).\nUsing one or more of the pre-defined workflows is recommended because they enforce an order of operations that is required for a successful configuration. If you create a custom workflow using individual actions (described below), you must ensure that the order of operations is correct. For example, you must ensure that the AAF password is set before installing an AAF application.\nOnce you click\nLaunch\nand the Apply Workflow(s) process begins, the operations are executed one after another, resulting in the desired configuration. Please note that this process undertakes one operation step only at each device communication interval. The overall configuration may take few device heartbeat periods. The device will reboot one or more times during this process.\nSelecting Systems\nBefore applying workflows, you must select one or more systems from the list on the Monitor > Systems screen.\nApply Workflow(s) is not available when you select all systems in your company. Also, if you select systems running different firmware versions, AirVantage prompts you to select systems running the same firmware.\nHint\n: Select systems of the same device type and firmware.\nBasic Workflow\nConfigure device communication\nHeartbeat\nis the time interval that the device will communicate to AirVantage.\nAll relevant jobs that are in queue in ALMS are triggered based on the heartbeat. This timer cannot be set to less than 15 minutes, unless your account is in the ALMS ARA offer class. Note that the heartbeat will consume around 1.4 Kb of data.\nClicking\nMore\nexpands the window to show two additional timers that relate to the status icon that appears on the Monitor > Systems page. You can enter a timeout value to change the green icon to amber and from amber to red.\nStatus report\nis the time interval for collecting the group of status data from the device for display in AirVantage.\nFor information on status report data and airtime usage, see\nDefault Status Report Parameters and associated data consumption\n.\nAdditional datasets\nis the time interval for collecting a user-defined set of data from the device for display in AirVantage. You need to create a Dataset data set in AirVantage in advance to configure this option.\nTo create a dataset, go to the Configure > Datasets page. Click on the\n+\nto begin the process.\nSet ACEmanager Password\nThis operation appears for systems using LWM2M, and allows you to set a unique password for the device. Sierra Wireless recommends changing the unique default passwords on all devices.\nInstall Firmware\nThis option lets you apply a firmware update to the systems.\nPrior to selecting this option ensure that you are selecting a valid upgrade version. Some older versions of AirLink ALEOS firmware have dependencies that may require an incremental update. In that case apply the valid version. You will be able to apply the latest version once the systems are registered and communicating with AirVantage.\nInstall AAF Application workflow\nYou can add the Install AAF Application workflow to the Basic workflow if you wish to install an AAF application such as AVTA.\nTo add an AAF application:\nSet an AAF password. The AAF password can be 4 to 100 characters long and can contain a mixture of letters, numbers, and/or special characters. The password is case sensitive.\nSelect the desired AAF application from the list or by searching (click the search icon).\nTo install additional AAF applications, add \u201CInstall Application\u201D as an individual action (see\nCreating a Custom Workflow\nbelow).\nConfigure AMR workflow\nThis workflow is available only to the Advanced Mobility Reporting (AMR) offer class, and for telemetry-capable systems. For more information about prerequisites for AMR, see\nReporting\n.\nTo configure ALMS AMR:\nInstall the latest firmware for your device. For an AirLink MP70, ensure that ALEOS 4.9.0 or later is installed.\nConfigure Telemetry for your system by ensuring that Driver Behavior Detection, Location Service, Direct Vehicle Bus Data Collection and Dead Reckoning are enabled. Note that the settings for Configuring Telemetry differ slightly depending on the ALEOS version. However, the final functionality is the same.\nSet an AAF password.\nInstall the latest version of the AirLink Vehicle Telemetry Application (AVTA).\nSelect the Start Application. This is the application that starts running after the Install Application process is complete. When configuring AMR, select the same version of AVTA for both Install Application and Start Application.\nSet the AVTA password.\nClick\nLaunch\n.\nCreating a Custom Workflow\nYou can customize your workflows by adding actions to an existing Workflow or by creating your own workflow from the individual actions available in the left column of the Apply Workflow(s) window.\nClick\nShow individual actions\nto display the list of available actions, and then drag and drop actions into the main window to create a workflow.\nTo remove an action, click its \u201Cbin\u201D icon (\n) or drag the action back into the left-hand column.\nMost of the individual actions are described in the sections above, and include:\nConfigure communication\nInstall Firmware\nApply Labels\nInstall Application\nReboot System\nSet AAF Password\nSet AVTA password\nApply Template\nBefore selecting a configuration template to apply to your system(s), you must create an ALEOS configuration template in AirVantage.\nTo create a template, go to the Configure > Templates page. Click the\n+\nto begin the process. You have the option to create a new template from an existing device (select\nFrom a System\n) or\nFrom an Application (from Scratch)\n.\nThe following individual actions may appear when applying a workflow to multiple systems:\nBulk edit ACEmanager Password\nBulk edit M3DA Password\nBulk edit MQTT Password\nBulk editing passwords in a custom workflow\nBefore launching a workflow that includes a \u201Cbulk edit passwords\u201D action, you must edit, save, and upload a .csv file that includes passwords for all affected systems.\nThe bulk edit password actions also appear in the pre-defined workflows when applying a workflow to multiple systems. For example,\nBulk edit ACEmanager Password\nappears in the Basic Workflow, and\nBulk edit M3DA Password\nappears in the Install AAF Application workflow. The procedure below applies to all \u201Cbulk edit passwords\u201D scenarios.\nTo perform a \u201Cbulk edit passwords\u201D action:\nDrag the desired action into the workflow, in the order you wish the action to be applied.\nClick\nGenerate\n. AirVantage generates a .csv file based on the systems you previously selected.\nClick\nDownload your template\u2026\n.\nOpen the downloaded .csv file. The file is populated with system-identifying information, and includes an empty column for passwords.\nFill in the password column with the passwords you want to apply to your systems.\nEnsure that you create unique passwords that include at least 1 letter, 1 number and 1 special character. Passwords must be at least 8 characters in length.\nSave the .csv file.\nOn the Apply Workflow(s) screen, click"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsx)(t.li,{children:"Select a CSV\n, select your file, and click\nOpen\n.\nAirVantage warns you about weak passwords if your .csv file contains passwords that don\u2019t meet the minimum requirement.\nIf you have no other actions to configure for your workflow, click\nLaunch\n."}),"\n"]})]})}function p(e={}){let{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(d,{...e})}):d(e)}},8453(e,t,o){o.d(t,{R:()=>i,x:()=>r});var n=o(6540);let a={},s=n.createContext(a);function i(e){let t=n.useContext(s);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:i(e.components),n.createElement(s.Provider,{value:t},e.children)}}}]);